export const getTasks = async (args, context) => {
  return context.entities.Task.findMany({
    orderBy: { id: 'asc' }
  });
};

export const getProjectStats = async (args, context) => {
  const projects = await context.entities.Project.findMany({
    include: {
      tasks: true
    },
    orderBy: { id: 'asc' }
  });
  return projects.map(p => ({
    id: p.id,
    name: p.name,
    totalTasks: p.tasks.length,
    doneTasks: p.tasks.filter(t => t.done).length
  }));
};

export const addTask = async (args, context) => {
  const projectId = parseInt(args.projectId);
  if (!args.title) {
    throw new Error('Title is required');
  }
  if (isNaN(projectId)) {
    throw new Error('Valid projectId is required');
  }
  return context.entities.Task.create({
    data: {
      title: args.title,
      done: false,
      project: {
        connect: { id: projectId }
      }
    }
  });
};

export const toggleTask = async (args, context) => {
  const taskId = parseInt(args.id);
  if (isNaN(taskId)) {
    throw new Error('Valid task id is required');
  }
  const task = await context.entities.Task.findUnique({
    where: { id: taskId }
  });
  if (!task) {
    throw new Error(`Task with id ${args.id} not found`);
  }
  return context.entities.Task.update({
    where: { id: taskId },
    data: { done: !task.done }
  });
};

