export const getTasks = async (args: any, context: any) => {
  return context.entities.Task.findMany({
    orderBy: { id: 'asc' }
  });
};

export const getProjectStats = async (args: any, context: any) => {
  const projects = await context.entities.Project.findMany({
    include: {
      tasks: true
    },
    orderBy: { id: 'asc' }
  });
  return projects.map((p: any) => ({
    id: p.id,
    name: p.name,
    totalTasks: p.tasks.length,
    doneTasks: p.tasks.filter((t: any) => t.done).length
  }));
};

export const addTask = async (args: { projectId: any; title: string }, context: any) => {
  const projectId = parseInt(args.projectId);
  if (!args.title) {
    throw new Error('Title is required');
  }
  if (isNaN(projectId)) {
    throw new Error('Valid projectId is required');
  }
  return context.entities.Task.create({
    data: {
      title: args.title,
      done: false,
      project: {
        connect: { id: projectId }
      }
    }
  });
};

export const toggleTask = async (args: { id: any }, context: any) => {
  const taskId = parseInt(args.id);
  if (isNaN(taskId)) {
    throw new Error('Valid task id is required');
  }
  const task = await context.entities.Task.findUnique({
    where: { id: taskId }
  });
  if (!task) {
    throw new Error(`Task with id ${args.id} not found`);
  }
  return context.entities.Task.update({
    where: { id: taskId },
    data: { done: !task.done }
  });
};

export const devSeed = async (prismaClient: any) => {
  // Clear any prior projects/tasks first so the result is deterministic.
  await prismaClient.task.deleteMany({});
  await prismaClient.project.deleteMany({});

  // A project named `Work` containing two tasks titled `Ship release` (done) and `Write docs` (not done)
  const work = await prismaClient.project.create({
